{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@harmonyos-arkts/opencode-plugin",
  "version": "0.0.23",
  "description": "HarmonyOS Full-Lifecycle Development Assistant. Specialized in the complete development lifecycle of HarmonyOS applications, including project creation, UI development, state management, network requests, data storage, permission requests, performance optimization, testing, and release.",
  "type": "module",
  "license": "MIT",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build": "node scripts/build.mjs",
    "prepublishOnly": "npm run build",
    "test": "vitest run",
    "test:watch": "vitest"
  },
  "files": [
    "dist"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "harmonyos",
    "ArkTs"
  ],
  "dependencies": {
    "@opencode-ai/sdk": "latest",
    "diff": "7.0.0",
    "env-paths": "4.0.0",
    "jsonc-parser": "3.3.1",
    "turndown": "^7.2.2",
    "zod": "latest"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@types/diff": "^7.0.2",
    "@types/node": "^25.7.0",
    "@types/turndown": "^5.0.6",
    "esbuild": "^0.28.0",
    "typescript": "^5.7.3",
    "vitest": "^4.1.5"
  },
  "sideEffects": false,
  "engines": {
    "node": ">=18.0.0"
  }
}
